473	    /// Incremental request number. When response is received,
474	    /// if its request number does not equal to the current request number, response will be ignored.
475	    /// This is to avoid race conditions.
476	    let request_num = 0;
477	
478	    /// Save query in history only if it is different.
479	    let previous_query = '';
480	
481	    const current_url = new URL(window.location);
482	
483	    const server_address = current_url.searchParams.get('url');
484	    if (server_address) {
485	        document.getElementById('url').value = server_address;
486	    } else if (location.protocol != 'file:') {
487	        /// Substitute the address of the server where the page is served.
488	        document.getElementById('url').value = location.origin;
489	    }
490	
491	    /// Substitute user name if it's specified in the query string
492	    const user_from_url = current_url.searchParams.get('user');
493	    if (user_from_url) {
494	        document.getElementById('user').value = user_from_url;
