497	    function postImpl(posted_request_num, query)
498	    {
499	        const user = document.getElementById('user').value;
500	        const password = document.getElementById('password').value;
501	
502	        const server_address = document.getElementById('url').value;
503	
504	        const url = server_address +
505	            (server_address.indexOf('?') >= 0 ? '&' : '?') +
506	            /// Ask server to allow cross-domain requests.
507	            'add_http_cors_header=1' +
508	            '&user=' + encodeURIComponent(user) +
509	            '&password=' + encodeURIComponent(password) +
510	            '&default_format=JSONCompact' +
511	            /// Safety settings to prevent results that browser cannot display.
512	            '&max_result_rows=1000&max_result_bytes=10000000&result_overflow_mode=break';
513	
514	        const xhr = new XMLHttpRequest;
515	
516	        xhr.open('POST', url, true);
517	
518	        xhr.onreadystatechange = function()
519	        {
520	            if (posted_request_num != request_num) {
521	                return;
522	            } else if (this.readyState === XMLHttpRequest.DONE) {
523	                renderResponse(this.status, this.response);
524	
525	                /// The query is saved in browser history (in state JSON object)
526	                /// as well as in URL fragment identifier.
527	                if (query != previous_query) {
528	                    const state = {
529	                        query: query,
530	                        status: this.status,
531	                        response: this.response.length > 100000 ? null : this.response  /// Lower than the browser's limit.
532	                    };
533	                    const title = "ClickHouse Query: " + query;
534	
535	                    let history_url = window.location.pathname + '?user=' + encodeURIComponent(user);
536	                    if (server_address != location.origin) {
537	                        /// Save server's address in URL if it's not identical to the address of the play UI.
538	                        history_url += '&url=' + encodeURIComponent(server_address);
539	                    }
540	                    history_url += '#' + window.btoa(query);
541	
542	                    if (previous_query == '') {
543	                        history.replaceState(state, title, history_url);
544	                    } else {
545	                        history.pushState(state, title, history_url);
546	                    }
547	                    document.title = title;
548	                    previous_query = query;
549	                }
550	            } else {
551	                //console.log(this);
552	            }
553	        }
554	
555	        document.getElementById('check-mark').style.display = 'none';
556	        document.getElementById('hourglass').style.display = 'inline-block';
557	
558	        xhr.send(query);
559	    }
