561	    function renderResponse(status, response) {
562	        document.getElementById('hourglass').style.display = 'none';
563	
564	        if (status === 200) {
565	            let json;
566	            try { json = JSON.parse(response); } catch (e) {}
567	
568	            if (json !== undefined && json.statistics !== undefined) {
569	                renderResult(json);
570	            } else if (Array.isArray(json) && json.length == 2 &&
571	                Array.isArray(json[0]) && Array.isArray(json[1]) && json[0].length > 1 && json[0].length == json[1].length) {
572	                /// If user requested FORMAT JSONCompactColumns, we will render it as a chart.
573	                renderChart(json);
574	            } else {
575	                renderUnparsedResult(response);
576	            }
577	            document.getElementById('check-mark').style.display = 'inline';
578	        } else {
579	            /// TODO: Proper rendering of network errors.
580	            renderError(response);
581	        }
582	    }
