644	    function formatReadable(number = 0, decimals = 2, units = []) {
645	        const k = 1000;
646	        const i = number ? Math.floor(Math.log(number) / Math.log(k)) : 0;
647	        const unit = units[i];
648	        const dm = unit ? decimals : 0;
649	        return Number(number / Math.pow(k, i)).toFixed(dm) + unit;
650	    }
