652	    function formatReadableBytes(bytes) {
653	        const units = [' B', ' KB', ' MB', ' GB', ' TB', ' PB', ' EB', ' ZB', ' YB'];
654	
655	        return formatReadable(bytes, 2, units);
656	    }
