688	        let is_null = (cell === null);
689	        let is_link = false;
690	
691	        /// Test: SELECT number, toString(number) AS str, number % 2 ? number : NULL AS nullable, range(number) AS arr, CAST((['hello', 'world'], [number, number % 2]) AS Map(String, UInt64)) AS map FROM numbers(10)
692	        let text;
693	        if (is_null) {
694	            text = 'ᴺᵁᴸᴸ';
695	        } else if (typeof(cell) === 'object') {
696	            text = JSON.stringify(cell);
697	        } else {
698	            text = cell;
699	
700	            /// If it looks like URL, create a link. This is for convenience.
701	            if (typeof(cell) == 'string' && cell.match(/^https?:\/\/\S+$/)) {
702	                is_link = true;
703	            }
704	        }
