706	        let node = document.createTextNode(text);
707	        if (is_link) {
708	            let link = document.createElement('a');
709	            link.appendChild(node);
710	            link.href = text;
711	            link.setAttribute('target', '_blank');
712	            node = link;
713	        }
714	
715	        if (settings.is_transposed) {
716	            td.className = 'left transposed';
717	        } else {
718	            td.className = settings.column_is_number[col_idx] ? 'right' : 'left';
719	        }
720	        if (is_null) {
721	            td.className += ' null';
722	        }
723	
724	        /// If it's a number, render bar in background.
725	        if (!settings.is_transposed && settings.column_need_render_bars[col_idx] && text > 0) {
726	            const ratio = 100 * text / settings.column_maximums[col_idx];
727	
728	            let div = document.createElement('div');
729	
730	            div.style.width = '100%';
731	            div.style.background = `linear-gradient(to right,
732	                var(--bar-color) 0%, var(--bar-color) ${ratio}%,
733	                transparent ${ratio}%, transparent 100%)`;
734	
735	            div.appendChild(node);
736	            node = div;
737	        }
738	
739	        td.appendChild(node);
740	        return td;
741	    }
