const use_url_credentials = location.protocol == 'file:';
if (use_url_credentials) {
    url += '&user=' + encodeURIComponent(user) +
        '&password=' + encodeURIComponent(password);
}

const xhr = new XMLHttpRequest;

xhr.open('POST', url, true);

/// Send the credentials in the "Authorization" header to avoid exposing them in URLs,
/// which can be logged by proxies or saved in the browser history.
